/**
 * FISHAO – Internationalization (i18n) Core Module
 * -------------------------------------------------------------
 * Single source of truth for supported languages, fallback chains, locales,
 * plural rules and localized formatting. Dictionaries live in data/i18n/:
 *   - ui_<code>.js      UI strings      (window.FISHAO_I18N_UI_<CODE>)
 *   - taxonomies.js     baits, waters, locations, cities ({ cs, en, pl } entries)
 *   - fish_names.js     fish names      ({ cs, en, pl } entries, generated by build_i18n.py)
 *
 * Adding a language = add an entry to LANGUAGES, create data/i18n/ui_<code>.js,
 * add the <code> column to taxonomies.js / fish_names.js and load the script in
 * index.html. Missing strings resolve through the language's fallback chain.
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'fishao_lang';
  var DEFAULT_LANG = 'cs';

  /**
   * Language registry.
   *  - fallback:     ordered languages consulted when a string is missing
   *  - locale:       BCP 47 locale for numbers / dates / plural rules
   *  - altNameLang:  language of the secondary fish name shown next to the main name
   *  - dateStyle:    'cs' (5. 1. 2026), 'iso' (2026-01-05) or 'intl' (Intl numeric)
   */
  var LANGUAGES = {
    cs: { code: 'cs', label: 'Čeština', short: 'CZ', flag: '🇨🇿', locale: 'cs-CZ', ogLocale: 'cs_CZ', fallback: [], altNameLang: 'en', dateStyle: 'cs' },
    en: { code: 'en', label: 'English', short: 'EN', flag: '🇬🇧', locale: 'en-US', ogLocale: 'en_US', fallback: ['cs'], altNameLang: 'cs', dateStyle: 'iso' },
    pl: { code: 'pl', label: 'Polski', short: 'PL', flag: '🇵🇱', locale: 'pl-PL', ogLocale: 'pl_PL', fallback: ['en', 'cs'], altNameLang: 'en', dateStyle: 'intl' },
    nl: { code: 'nl', label: 'Nederlands', short: 'NL', flag: '🇳🇱', locale: 'nl-NL', ogLocale: 'nl_NL', fallback: ['en', 'cs'], altNameLang: 'en', dateStyle: 'intl' },
    ro: { code: 'ro', label: 'Română', short: 'RO', flag: '🇷🇴', locale: 'ro-RO', ogLocale: 'ro_RO', fallback: ['en', 'cs'], altNameLang: 'en', dateStyle: 'intl' },
    tr: { code: 'tr', label: 'Türkçe', short: 'TR', flag: '🇹🇷', locale: 'tr-TR', ogLocale: 'tr_TR', fallback: ['en', 'cs'], altNameLang: 'en', dateStyle: 'intl' }
  };
  var LANGUAGE_ORDER = ['cs', 'en', 'pl', 'nl', 'ro', 'tr'];

  var hasWindow = typeof window !== 'undefined';

  function loadModule(globalName, path) {
    var mod = (hasWindow && window[globalName]) || null;
    if (!mod && typeof require !== 'undefined') {
      try { mod = require(path); } catch (e) { mod = null; }
    }
    return mod;
  }

  var ui = {};
  LANGUAGE_ORDER.forEach(function (code) {
    ui[code] = loadModule('FISHAO_I18N_UI_' + code.toUpperCase(), './i18n/ui_' + code + '.js') || {};
  });
  var taxonomies = loadModule('FISHAO_I18N_TAXONOMIES', './i18n/taxonomies.js') || {};
  var fishNames = loadModule('FISHAO_I18N_FISH_NAMES', './i18n/fish_names.js') || {};

  // -------------------------------------------------------------
  // Language helpers
  // -------------------------------------------------------------

  function isSupported(lang) {
    return typeof lang === 'string' && Object.prototype.hasOwnProperty.call(LANGUAGES, lang);
  }

  function normalizeLang(lang) {
    if (typeof lang !== 'string') return DEFAULT_LANG;
    var code = lang.toLowerCase().split(/[-_]/)[0];
    return isSupported(code) ? code : DEFAULT_LANG;
  }

  /** Ordered lookup chain for a language, e.g. pl -> [pl, en, cs]. */
  function getChain(lang) {
    var code = isSupported(lang) ? lang : (FISHAO_I18N.currentLang || DEFAULT_LANG);
    var chain = [code].concat(LANGUAGES[code].fallback || []);
    if (chain.indexOf(DEFAULT_LANG) === -1) chain.push(DEFAULT_LANG);
    return chain;
  }

  /** Initial language: ?lang= URL param > URL path prefix (/en/, /pl/) > <html lang> > saved choice > browser language > default. */
  function detectInitialLang() {
    try {
      if (hasWindow && window.location && typeof URLSearchParams !== 'undefined') {
        var urlLang = new URLSearchParams(window.location.search).get('lang');
        if (urlLang && isSupported(urlLang.toLowerCase())) return urlLang.toLowerCase();
      }
    } catch (e) { }
    try {
      if (hasWindow && window.location && typeof window.location.pathname === 'string') {
        var pathMatch = /^\/(en|pl|nl|ro|tr)(\/|$)/i.exec(window.location.pathname);
        if (pathMatch && isSupported(pathMatch[1].toLowerCase())) {
          return pathMatch[1].toLowerCase();
        }
        // Only treat root "/" as explicit Czech if the user came from a localized subpath on the same origin
        if ((window.location.pathname === '/' || window.location.pathname === '/index.html') &&
            typeof document !== 'undefined' && document.referrer) {
          var refUrl = new URL(document.referrer);
          if (refUrl.origin === window.location.origin && /^\/(en|pl|nl|ro|tr)(\/|$)/i.test(refUrl.pathname)) {
            return 'cs';
          }
        }
      }
    } catch (e) { }
    // Crawlers & headless renderers (Googlebot renders with navigator.language = en-US) must always
    // see the language declared by the URL, otherwise "/" renders as an English duplicate of "/en/".
    try {
      if (typeof navigator !== 'undefined' &&
          (navigator.webdriver ||
            /bot|crawl|spider|slurp|mediapartners|inspectiontool|lighthouse|headlesschrome|bingpreview|facebookexternalhit|embedly|discord/i.test(navigator.userAgent || ''))) {
        return DEFAULT_LANG;
      }
    } catch (e) { }
    try {
      var saved = typeof localStorage !== 'undefined' ? localStorage.getItem(STORAGE_KEY) : null;
      if (saved && isSupported(saved)) return saved;
    } catch (e) { }
    try {
      if (hasWindow && typeof document !== 'undefined' && document.documentElement) {
        var htmlLang = (document.documentElement.getAttribute('lang') || '').toLowerCase().split(/[-_]/)[0];
        if (htmlLang && htmlLang !== DEFAULT_LANG && isSupported(htmlLang)) return htmlLang;
      }
    } catch (e) { }
    try {
      if (typeof navigator !== 'undefined') {
        var prefs = navigator.languages || [navigator.language];
        for (var i = 0; i < prefs.length; i++) {
          var code = (prefs[i] || '').toLowerCase().split(/[-_]/)[0];
          if (isSupported(code)) return code;
        }
      }
    } catch (e) { }
    return DEFAULT_LANG;
  }

  /** Returns the first non-empty value of a { cs, en, pl } entry along the chain. */
  function resolveEntry(entry, lang) {
    if (!entry || typeof entry !== 'object') return '';
    var chain = getChain(lang);
    for (var i = 0; i < chain.length; i++) {
      var v = entry[chain[i]];
      if (typeof v === 'string' && v.trim()) return v;
    }
    return '';
  }

  var pluralRulesCache = {};
  function getPluralCategory(count, lang) {
    var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
    try {
      if (!pluralRulesCache[code]) {
        pluralRulesCache[code] = new Intl.PluralRules(LANGUAGES[code].locale);
      }
      return pluralRulesCache[code].select(count);
    } catch (e) {
      return count === 1 ? 'one' : 'other';
    }
  }

  /**
   * Diacritics-insensitive normalization used by fish search.
   * Polish "ł" and Turkish dotless "ı" do not decompose under NFD, so they are folded explicitly.
   */
  function norm(s) {
    var str = String(s || '');
    if (str.normalize) str = str.normalize('NFD');
    return str.replace(/[\u0300-\u036f]/g, '').replace(/ł/g, 'l').replace(/Ł/g, 'L').replace(/ı/g, 'i').replace(/İ/g, 'i').toLowerCase().trim();
  }

  function lookupKey(dict, key) {
    return dict ? dict[key] : undefined;
  }

  function lookupPlural(dict, key, count, lang) {
    if (!dict) return undefined;
    var cat = getPluralCategory(count, lang);
    if (dict[key + '_' + cat] !== undefined) return dict[key + '_' + cat];
    if (dict[key + '_other'] !== undefined) return dict[key + '_other'];
    return dict[key];
  }

  function interpolate(val, params) {
    if (!params || typeof val !== 'string') return val;
    Object.keys(params).forEach(function (p) {
      val = val.split('{' + p + '}').join(String(params[p]));
    });
    return val;
  }

  // -------------------------------------------------------------
  // Public API
  // -------------------------------------------------------------

  var FISHAO_I18N = {
    STORAGE_KEY: STORAGE_KEY,
    DEFAULT_LANG: DEFAULT_LANG,
    languages: LANGUAGES,
    languageOrder: LANGUAGE_ORDER,
    currentLang: DEFAULT_LANG,

    ui: ui,
    baits: taxonomies.baits || {},
    waters: taxonomies.waters || {},
    locations: taxonomies.locations || {},
    cities: taxonomies.cities || {},
    shop: taxonomies.shop || {},
    fishes: fishNames,

    isSupported: isSupported,
    normalizeLang: normalizeLang,
    getChain: getChain,
    resolveEntry: resolveEntry,
    getPluralCategory: getPluralCategory,
    norm: norm,

    getLanguages: function () {
      return LANGUAGE_ORDER.map(function (code) { return LANGUAGES[code]; });
    },

    getLocale: function (lang) {
      var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
      return LANGUAGES[code].locale;
    },

    /** Sets and persists the active language. Returns the normalized code. */
    setLang: function (lang) {
      var code = normalizeLang(lang);
      FISHAO_I18N.currentLang = code;
      try { if (typeof localStorage !== 'undefined') localStorage.setItem(STORAGE_KEY, code); } catch (e) { }
      return code;
    },

    /**
     * Translate a UI key.
     *   t(key)                       plain lookup
     *   t(key, { name: 'X' })        {placeholder} interpolation
     *   t(key, 'Fallback text')      inline fallback when the key is unknown everywhere
     *   t(key, params, 'Fallback')   both
     * When params.count is a number, plural variants key_one / key_few / key_many /
     * key_other (Intl.PluralRules categories) are preferred over the bare key.
     */
    t: function (key, params, fallback) {
      if (!key) return '';
      var actualParams = (params && typeof params === 'object') ? params : ((fallback && typeof fallback === 'object') ? fallback : null);
      var hasCount = actualParams && typeof actualParams.count === 'number' && isFinite(actualParams.count);
      var chain = getChain();
      var val;
      for (var i = 0; i < chain.length && val === undefined; i++) {
        var dict = ui[chain[i]];
        val = hasCount ? lookupPlural(dict, key, actualParams.count, chain[i]) : lookupKey(dict, key);
      }
      if (val === undefined) {
        if (typeof params === 'string') val = params;
        else if (typeof fallback === 'string') val = fallback;
        else val = key;
      }
      return interpolate(val, actualParams);
    },

    /** Returns true when a key exists in the active language itself (no fallback). */
    hasOwnTranslation: function (key, lang) {
      var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
      return !!(ui[code] && ui[code][key] !== undefined);
    },

    getFishName: function (fish, lang) {
      if (!fish) return '';
      var id = (typeof fish === 'object') ? fish.id : fish;
      var name = resolveEntry(fishNames[id], lang);
      if (name) return name;
      if (typeof fish === 'object' && fish.name) return fish.name;
      return '#' + id;
    },

    /**
     * Secondary fish name in the language's altNameLang (exact, no fallback).
     * Returns '' when it is missing or identical to the displayed name.
     */
    getAltFishName: function (fish, lang) {
      if (!fish) return '';
      var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
      var altLang = LANGUAGES[code].altNameLang;
      var id = (typeof fish === 'object') ? fish.id : fish;
      var entry = fishNames[id];
      var alt = (entry && entry[altLang]) || '';
      if (!alt) return '';
      return alt !== FISHAO_I18N.getFishName(fish, code) ? alt : '';
    },

    getLocationName: function (loc, lang) {
      if (!loc) return '';
      return resolveEntry(FISHAO_I18N.locations[loc], lang) || loc;
    },

    getBaitName: function (bait, lang) {
      if (!bait) return '';
      return resolveEntry(FISHAO_I18N.baits[bait], lang) || bait;
    },

    getWaterName: function (water, lang) {
      if (!water) return '';
      return resolveEntry(FISHAO_I18N.waters[water], lang) || water;
    },

    getShopItemText: function (key, lang) {
      if (!key) return '';
      return resolveEntry(FISHAO_I18N.shop[key], lang) || '';
    },

    /** Localized city name for a timezone city (exact language only, else raw name). */
    getCityName: function (city, lang) {
      if (!city) return '';
      var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
      var entry = FISHAO_I18N.cities[city];
      return (entry && entry[code]) || city;
    },

    /** Formats a month/day pair (1-based month), e.g. "5. 1." / "Jan 5" / "5 sty". */
    formatDayMonth: function (month, day, lang) {
      var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
      if (LANGUAGES[code].dateStyle === 'cs') return day + '. ' + month + '.';
      try {
        return new Intl.DateTimeFormat(LANGUAGES[code].locale, { day: 'numeric', month: 'short', timeZone: 'UTC' })
          .format(new Date(Date.UTC(2000, month - 1, day)));
      } catch (e) {
        return day + '.' + month + '.';
      }
    },

    /** Formats an ISO date (YYYY-MM-DD) according to the language's dateStyle. */
    formatDate: function (isoDate, lang) {
      if (!isoDate) return '';
      var parts = String(isoDate).split('-');
      if (parts.length !== 3) return isoDate;
      var code = isSupported(lang) ? lang : FISHAO_I18N.currentLang;
      var style = LANGUAGES[code].dateStyle;
      if (style === 'cs') return parseInt(parts[2], 10) + '. ' + parseInt(parts[1], 10) + '. ' + parts[0];
      if (style === 'iso') return isoDate;
      try {
        return new Intl.DateTimeFormat(LANGUAGES[code].locale, { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'UTC' })
          .format(new Date(Date.UTC(+parts[0], +parts[1] - 1, +parts[2])));
      } catch (e) {
        return isoDate;
      }
    },

    /** All known names of a fish across every language (used by search and bulk import). */
    getFishNames: function (fish) {
      if (!fish) return [];
      var id = (typeof fish === 'object') ? fish.id : fish;
      var list = [];
      function addName(n) {
        if (n && typeof n === 'string') {
          var trimmed = n.trim();
          if (trimmed && list.indexOf(trimmed) === -1) list.push(trimmed);
        }
      }
      if (typeof fish === 'object' && fish.name) addName(fish.name);
      var entry = fishNames[id];
      if (entry && typeof entry === 'object') {
        Object.keys(entry).forEach(function (k) { addName(entry[k]); });
      }
      return list;
    },

    matchesFishSearch: function (fish, query) {
      if (!fish || !query) return false;
      var q = norm(query);
      if (!q) return false;
      var id = String((typeof fish === 'object') ? fish.id : fish);
      if (id === q || ('#' + id) === q) return true;

      var names = FISHAO_I18N.getFishNames(fish);
      var tokens = q.split(/\s+/).filter(Boolean);
      for (var i = 0; i < names.length; i++) {
        var nNorm = norm(names[i]);
        if (nNorm.indexOf(q) !== -1) return true;
        if (tokens.length > 1 && tokens.every(function (tok) { return nNorm.indexOf(tok) !== -1; })) {
          return true;
        }
      }
      return false;
    },

    /** Returns "EN: Name" when the query matched a fish name in another language only. */
    getMatchingFishAltName: function (fish, query) {
      if (!fish || !query) return '';
      var q = norm(query);
      if (!q) return '';
      if (norm(FISHAO_I18N.getFishName(fish)).indexOf(q) !== -1) return '';

      var id = (typeof fish === 'object') ? fish.id : fish;
      var entry = fishNames[id];
      if (!entry) return '';
      var curLang = FISHAO_I18N.currentLang;
      var otherLangs = LANGUAGE_ORDER.filter(function (k) { return k !== curLang && entry[k]; });
      for (var i = 0; i < otherLangs.length; i++) {
        var alt = entry[otherLangs[i]];
        if (norm(alt).indexOf(q) !== -1) {
          return otherLangs[i].toUpperCase() + ': ' + alt;
        }
      }
      return '';
    },

    isLangLoaded: function (lang) {
      var code = normalizeLang(lang);
      return !!(ui[code] && Object.keys(ui[code]).length > 0);
    },

    ensureLangLoaded: function (lang) {
      var code = normalizeLang(lang);
      if (FISHAO_I18N.isLangLoaded(code)) {
        return Promise.resolve(true);
      }
      if (!hasWindow || typeof document === 'undefined') {
        return Promise.resolve(false);
      }
      if (!FISHAO_I18N._langPromises) {
        FISHAO_I18N._langPromises = {};
      }
      if (FISHAO_I18N._langPromises[code]) {
        return FISHAO_I18N._langPromises[code];
      }
      FISHAO_I18N._langPromises[code] = new Promise(function (resolve) {
        var globalName = 'FISHAO_I18N_UI_' + code.toUpperCase();
        if (window[globalName]) {
          ui[code] = window[globalName];
          resolve(true);
          return;
        }
        var bundledUrl = (window.FISHAO_I18N_BUNDLES && window.FISHAO_I18N_BUNDLES[code]) || null;
        var script = document.createElement('script');
        script.src = bundledUrl
          ? ((bundledUrl.charAt(0) === '/' || /^https?:\/\//i.test(bundledUrl)) ? bundledUrl : ('/' + bundledUrl))
          : ('/data/i18n/ui_' + code + '.js?v=7.7');
        script.async = true;
        script.onload = function () {
          ui[code] = window[globalName] || {};
          resolve(true);
        };
        script.onerror = function () {
          delete FISHAO_I18N._langPromises[code];
          resolve(false);
        };
        document.head.appendChild(script);
      });
      return FISHAO_I18N._langPromises[code];
    }
  };

  FISHAO_I18N.currentLang = detectInitialLang();

  if (hasWindow) {
    window.FISHAO_I18N = FISHAO_I18N;
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = FISHAO_I18N;
  }
})();
